preferences.addEventListener('submit',e=>{e.preventDefault();try{channelDefaults=saveChannelDefaults(preferenceStorage(),repo,Object.fromEntries(Object.keys(DEFAULT_CHANNELS).map(key=>[key,preferences.elements[key].checked])));$('#channel-defaults-status').textContent='Defaults saved for this repository in this browser. Existing campaigns are unchanged.';}catch{$('#channel-defaults-status').textContent='This browser could not save defaults. Your existing defaults are unchanged.';}});
