const safeURL=u=>{try{const x=new URL(u);return x.protocol==='https:'?x.href:''}catch{return ''}};
const campaignImage=(c,k)=>safeURL(c.images?.[k]||c.results?.[k]?.image||(k==='feed'?c.flyerUrl:''))||(c.demo?'':`./media/${encodeURIComponent(c.year)}/${encodeURIComponent(c.id)}-${k}.jpg`);
const format=(d,options={})=>d?new Intl.DateTimeFormat('en-US',{timeZone:config.timezone,month:'short',day:'numeric',hour:'numeric',minute:'2-digit',...options}).format(new Date(d)):'Not recorded';
function notice(message){$('#notice').textContent=message;$('#notice').classList.add('visible');}
function view(name){for(const s of ['dashboard','archive','settings'])$('#view-'+s).hidden=s!==name;document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===name;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});const heading=$('#view-'+name+' h1');heading.tabIndex=-1;heading.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function typeName(id){return config.eventTypes.find(t=>t.id===id)?.name||id||'Event';}
const groupmeEnabled=()=>config.integrations?.groupme?.enabled!==false;
const groupmeBotMode=()=>config.integrations?.groupme?.mode==='bot';
function channelSchedule(c,k){if(k==='groupme'){if(groupmeBotMode()){if(c.campaign?.groupme?.enabled!==true||c.campaign?.groupme?.announce!==true)return 'Disabled';return format(fireTime({...c,campaign:{...c.campaign,feed:{...c.campaign?.feed,enabled:true}}},'feed',config.timezone));}return c.campaign?.groupme?.enabled===false?'Disabled':'On next dispatcher run';}return c.campaign?.[k]?.enabled?format(fireTime(c,k,config.timezone)):'Disabled';}
const channels=()=>groupmeEnabled()?['feed','story','groupme']:['feed','story'];
function status(c){if(c.cancelled)return 'cancelled';const values=channels().map(k=>c.status?.[k]||'pending');return values.includes('failed')?'failed':values.length&&values.every(x=>x==='skipped')?'skipped':values.length&&values.every(x=>['done','skipped'].includes(x))?'done':'pending';}
function channelStateLabel(c,k){const state=c.status?.[k]||'pending';if(state==='done')return 'Posted';if(state==='pending')return 'Pending';if(state==='failed')return 'Failed';if(state==='skipped'){try{if(channelSchedule(c,k)==='Disabled')return 'Off';}catch{}return scheduleWarnings(c,config).some(w=>w.channel===k&&w.state==='missed')?'Missed window':'Skipped';}return state;}
// Publishing receipts differ for bot announcements and legacy GroupMe events.
function postedTime(c,k){const r=c.results?.[k]||{};return k==='groupme'&&groupmeBotMode()?r.botSentAt||r.postedAt||r.createdAt:r.postedAt||r.createdAt;}
function stepTrack(c){return `<div class="steps">${channels().map(k=>{const state=c.status?.[k]||'pending';let scheduled='On next dispatcher run';try{scheduled=channelSchedule(c,k);}catch{scheduled='Schedule needs review';}const actual=state==='done'?postedTime(c,k):null,label=k==='groupme'?'GroupMe':k==='feed'?'Feed':'Story';return `<div class="step-row"><span class="status-dot ${esc(state)}" aria-hidden="true">${state==='done'?'✓':state==='failed'?'!':state==='skipped'?'–':''}</span><div><strong${k==='groupme'?' title="GroupMe announcement"':''}>${label}</strong><span class="step-status">${esc(channelStateLabel(c,k))}</span>${actual?`<time datetime="${esc(actual)}">${esc(format(actual))}</time>`:state==='done'?'<span class="step-time">Time not recorded</span>':`<span class="step-time">${esc(scheduled)}</span>`}</div></div>`;}).join('')}</div>`;}
function campaignWarnings(c){
 const warnings=scheduleWarnings(c,config);
 for(const channel of channels()){
  const result=c.results?.[channel]||{},label=channel==='groupme'?'GroupMe announcement':`Instagram ${channel}`;
  if(c.status?.[channel]==='failed'||result.error||result.botError){const error=result.error||result.botError;warnings.push({channel,state:'failed',message:`${label} requires attention. ${typeof error==='string'?error:error?.hint||error?.code||'Publication failed; review the campaign timeline.'}`});}
 }
 return warnings;
}
function scheduleWarningMarkup(c){return campaignWarnings(c).map(w=>`<p class="schedule-warning" role="alert" data-channel="${esc(w.channel)}" data-state="${esc(w.state)}">${esc(w.message)}</p>`).join('');}
function cardWarningMarkup(c){
 const warnings=campaignWarnings(c);if(!warnings.length)return '';
 const first=warnings[0],label=first.channel==='groupme'?'GroupMe announcement':`Instagram ${first.channel}`;
 const summary=first.state==='failed'?`${label} requires attention.`:first.state==='missed'?`${label} missed its publishing window.`:`${label} is awaiting a late dispatcher run.`;
 return `<div class="card-warnings" role="status"><span class="card-warning-icon" aria-hidden="true">⚠</span><p><strong>${warnings.length} ${warnings.length===1?'warning':'warnings'}:</strong> ${esc(summary)}${warnings.length>1?' Review campaign for all issues.':''}</p></div>`;
}
function card(c){const date=new Date(c.start),img=campaignImage(c,'feed'),state=status(c);return `<article class="campaign-card ${c.cancelled?'cancelled':''}"><div class="card-art">${img?`<img src="${esc(img)}" alt="" loading="lazy">`:''}<span class="art-label">${esc(typeName(c.type)).toUpperCase()}<small>${esc(config.chapterName)}</small></span><span class="art-date">${format(date,{day:'2-digit',month:undefined,hour:undefined,minute:undefined})}<small>${format(date,{month:'short',day:undefined,hour:undefined,minute:undefined}).toUpperCase()}</small></span></div><div class="card-body"><div class="card-title-row"><h3>${esc(c.title)}</h3><span class="badge ${state}">${state==='done'?'✓ ':state==='failed'?'! ':state==='skipped'?'– ':''}${state}</span></div><div class="card-details"><p class="card-info"><span aria-hidden="true">◷</span><span>${esc(format(c.start))}</span></p><p class="card-info"><span aria-hidden="true">⌖</span><span>${esc(c.location?.name||c.location||'Location to be confirmed')}</span></p>${c.food?'<span class="badge food-chip">Food provided</span>':''}</div>${campaignInsightsMarkup(c,config)}${stepTrack(c)}${cardWarningMarkup(c)}</div><div class="card-footer"><button data-detail="${esc(c.id)}" aria-label="View campaign: ${esc(c.title)}">View campaign →</button>${c.demo?'<span class="badge example">Example</span>':`<small>${esc(c.year)}</small>`}</div></article>`;}

function archiveRow(c){const image=campaignImage(c,'feed'),latest=latestInsightsSnapshot(c),reach=recordedMetric(latest,'reach'),likes=recordedMetric(latest,'likes');return `<article class="archive-row"><img class="archive-thumb" src="${esc(image)}" alt="${esc(c.title)} feed flyer" loading="lazy"><div class="archive-main"><h3>${esc(c.title)}</h3><p>${esc(format(c.start))} · ${esc(c.year)}</p><div class="card-meta" style="margin:10px 0 0"><span class="badge ${status(c)}">${status(c)==='done'?'✓ ':status(c)==='failed'?'! ':status(c)==='skipped'?'– ':''}${status(c)}</span>${c.demo?'<span class="badge example">Example</span>':''}</div></div><span class="badge">${esc(typeName(c.type))}</span><div class="archive-stats"><span><strong>${reach==null?'—':esc(Number(reach).toLocaleString())}</strong>Reach</span><span><strong>${likes==null?'—':esc(Number(likes).toLocaleString())}</strong>Likes</span></div><button data-detail="${esc(c.id)}" aria-label="View ${esc(c.title)}">View →</button></article>`;}

function updateCampaignRail(){
 const rail=$('#campaign-list'),controls=$('#campaign-rail-controls');if(!rail||!controls)return;
 const overflowing=matchMedia('(min-width:1000px)').matches&&rail.scrollWidth>rail.clientWidth+2;
 controls.hidden=!overflowing;$('#campaign-previous').disabled=rail.scrollLeft<=2;$('#campaign-next').disabled=rail.scrollLeft>=rail.scrollWidth-rail.clientWidth-2;
}
for(const [selector,direction] of [['#campaign-previous',-1],['#campaign-next',1]])$(selector).addEventListener('click',()=>{const rail=$('#campaign-list'),card=rail.querySelector('.campaign-card');rail.scrollBy({left:direction*((card?.getBoundingClientRect().width||360)+20),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});
$('#campaign-list').addEventListener('scroll',updateCampaignRail,{passive:true});
new ResizeObserver(updateCampaignRail).observe($('#campaign-list'));
setInterval(()=>{if(config){const now=Date.now(),signature=homeCampaigns(campaigns,now).map(c=>c.id+'|'+c.year+'|'+(Date.parse(c.end||c.start)<now)).join(';');if(signature!==homeCampaignSignature)render();}},60000);
function render(){academicYearsController.refresh();$('#campaign-list').setAttribute('aria-busy','false');const now=Date.now(), upcoming=campaigns.filter(c=>!c.cancelled&&!c.archived&&Date.parse(c.end||c.start)>=now).sort((a,b)=>Date.parse(a.start)-Date.parse(b.start)),visible=homeCampaigns(campaigns,now);homeCampaignSignature=visible.map(c=>c.id+'|'+c.year+'|'+(Date.parse(c.end||c.start)<now)).join(';');$('#campaign-list').innerHTML=visible.map(card).join('')||(campaigns.length?'<div class="empty"><strong>No upcoming or recent events.</strong>Past events remain in the archive. Events leave this page 24 hours after they end.<br><button data-view="archive">Browse archive →</button></div>':'<div class="empty"><strong>No campaigns yet. Start with one event.</strong>Choose a calendar suggestion below, or create your own campaign.<br><button class="primary" data-new-campaign>Create a campaign ＋</button></div>');$('#campaign-list').classList.toggle('few-campaigns',visible.length>0&&visible.length<=2);updateCampaignRail();const demo=campaigns.some(c=>c.demo);$('#stats').innerHTML=[['Upcoming events',upcoming.length,'Campaigns for upcoming events','◷'],['Feed & story steps',upcoming.reduce((n,c)=>n+['feed','story'].filter(k=>c.campaign?.[k]?.enabled&&c.status?.[k]==='pending').length,0),'Waiting for their scheduled time','◫'],['Campaigns to review',campaigns.filter(c=>!c.cancelled&&(status(c)==='failed'||scheduleWarnings(c,config).some(w=>w.state==='missed'))).length,'Failed or missed publishing steps','!'],['Archived campaigns',campaigns.filter(c=>Date.parse(c.end||c.start)<now).length,'A record for the next team','▤']].map(([label,n,help,icon])=>`<div class="stat ${label==='Campaigns to review'&&n>0?'attention':''}"><span class="stat-label">${label}</span><strong>${n}</strong><small>${demo?'Includes labeled examples · ':''}${help}</small></div>`).join('');if(!calendarSuggestions)calendarSuggestions=mountCalendarSuggestions({container:$('#suggestions'),candidates,campaigns,format,esc,timezone:config.timezone});else calendarSuggestions.update({candidates,campaigns,timezone:config.timezone});renderCalendarChanges();renderArchive();}
function renderCalendarChanges(){const changes=calendarChanges.map(change=>({change,campaign:campaigns.find(c=>c.source?.uid&&c.source.uid===change.source?.uid)})).filter(x=>x.campaign);$('#calendar-updates-section').hidden=!changes.length;$('#calendar-updates').innerHTML=changes.map(({change,campaign:c})=>{const differences=change.differences||[],labels={title:'Title',start:'Start',end:'End',location:'Location',description:'Description'},show=(v,k)=>['start','end'].includes(k)&&Number.isFinite(Date.parse(v))?format(v):v||'Not provided';return `<div class="suggestion calendar-difference"><div><strong>${esc(change.title||c.title)}</strong><p>${change.comparison==='calendar-baseline'?'Calendar changed since this campaign was created.':'Calendar and campaign details differ; customized wording may be intentional.'} Saved campaign details have not been changed.</p>${change.updated?`<p class="field-help">Calendar entry last updated ${esc(format(change.updated))}.</p>`:''}${differences.length?`<details><summary>Compare ${differences.map(d=>esc(labels[d.field]||d.field).toLowerCase()).join(', ')}</summary><dl>${differences.map(d=>`<div><dt>${esc(labels[d.field]||d.field)}</dt><dd><b>Campaign:</b> ${esc(show(d.campaign,d.field))}<br><b>Calendar:</b> ${esc(show(d.current,d.field))}</dd></div>`).join('')}</dl></details>`:'<p class="field-help">The next calendar sync will refresh this comparison. Open the campaign to review; no changes are applied automatically.</p>'}</div><button data-detail="${esc(c.id)}">Review campaign →</button></div>`;}).join('');}

function renderArchive(){const query=$('#search').value.trim().toLowerCase(), year=$('#year-filter').value, type=$('#type-filter').value, state=$('#status-filter').value;const list=campaigns.filter(c=>(!year||c.year===year)&&(!type||c.type===type)&&(!state||status(c)===state)&&JSON.stringify([c.title,c.description,c.location,c.notes]).toLowerCase().includes(query)).sort((a,b)=>Date.parse(b.start)-Date.parse(a.start));$('#archive-list').innerHTML=list.map(archiveRow).join('')||'<div class="empty"><strong>'+ (campaigns.length?'No matching campaigns.':'Your archive starts here.')+'</strong>'+(campaigns.length?'Try a different search or clear the filters.':'Saved campaigns and their results will appear here.')+'</div>';$('#archive-count').textContent=`${list.length} ${list.length===1?'campaign':'campaigns'}${query||year||type||state?' match your filters':' in the archive'}`;$('#clear-filters').hidden=!(query||year||type||state);const groups=new Map();for(const c of campaigns){const item=latestInsightsSnapshot(c),reach=recordedMetric(item,'reach');if(reach===null)continue;const key=`${typeName(c.type)}|${c.year}|${c.demo?'Example':'Recorded'}`,values=groups.get(key)||[];values.push(reach);groups.set(key,values);}$('#comparison').innerHTML=groups.size?`<div class="comparison-bars" role="group" aria-label="Average feed reach by event type and academic year">${[...groups].map(([k,a])=>{const [type,year,data]=k.split('|'),mean=Math.round(a.reduce((n,x)=>n+x,0)/a.length),max=Math.max(1,...[...groups.values()].map(v=>v.reduce((n,x)=>n+x,0)/v.length));return `<div class="comparison-row"><p>${esc(type)}<small>${esc(year)} · ${esc(data)}</small></p><div class="comparison-track"><span class="comparison-bar ${year===config.activeYear?'current':''}" style="width:${Math.max(1,mean/max*100)}%"></span></div><span class="comparison-value">${mean.toLocaleString()}</span></div>`;}).join('')}</div><p class="field-help">Average feed reach: one latest feed snapshot per campaign. Example data is labeled separately.</p>`:'<p class="subtle">Reach comparisons appear when insights snapshots have been recorded.</p>' ;}
function populateFilters(){const old=$('#year-filter').value;$('#year-filter').innerHTML='<option value="">All years</option>'+[...new Set(campaigns.map(c=>c.year))].sort().reverse().map(y=>`<option>${esc(y)}</option>`).join('');$('#year-filter').value=old;$('#type-filter').innerHTML='<option value="">All types</option>'+config.eventTypes.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');}
const advertisingFields={foodDetails:{label:'Food details',max:160},rsvpUrl:{label:'RSVP link',max:2048},rsvpDeadline:{label:'RSVP deadline'},audience:{label:'Audience',max:200},cost:{label:'Cost',max:100},preparation:{label:'Preparation',max:250},speaker:{label:'Speaker',max:200},benefit:{label:'Benefit',max:250},accessibilityContact:{label:'Accessibility contact',max:200}};
function advertisingURL(value){try{const url=new URL(value);return url.protocol==='https:'&&!url.username&&!url.password?url.href:'';}catch{return '';}}
function readAdvertising(){const result={};for(const [key,field] of Object.entries(advertisingFields)){let value=form.elements[key].value.trim();if(!value)continue;if(field.max&&value.length>field.max)throw Error(`${field.label} must be ${field.max} characters or fewer.`);if(key==='rsvpUrl'&&!advertisingURL(value))throw Error('RSVP link must be an absolute HTTPS URL without a username or password.');if(key==='rsvpDeadline')value=fromLocal(value,config.timezone);result[key]=value;}return result;}
function advertisingDetail(c){const values=c.advertising||{},rows=Object.entries(advertisingFields).filter(([key])=>typeof values[key]==='string'&&values[key].trim()&&(key!=='foodDetails'||c.food)).map(([key,field])=>{let value=esc(values[key]);if(key==='rsvpUrl'){const url=advertisingURL(values[key]);value=url?`<a href="${esc(url)}" target="_blank" rel="noreferrer">${esc(values[key])} ↗</a>`:value;}if(key==='rsvpDeadline'){try{value=esc(format(values[key]))+' · '+esc(timeZoneName(values[key],config.timezone));}catch{value=esc(values[key]);}}return `<dt>${esc(field.label)}</dt><dd style="white-space:pre-wrap">${value}</dd>`;});return rows.length?'<h3>Event extras</h3><dl>'+rows.join('')+'</dl>':'';}
const flyerStyles={'refined-blueprint':'Refined Blueprint','editorial-poster':'Editorial Poster','assembly-card':'Assembly Card',blueprint:'Blueprint (legacy)',editorial:'Editorial (legacy)'};
function restoreFlyerStyle(c){const selected=c?(c.template||config.eventTypes.find(t=>t.id===c.type)?.template||config.defaultTemplate||'editorial'):(config.defaultTemplate||'refined-blueprint');form.elements.template.innerHTML=Object.entries(flyerStyles).filter(([id])=>!['blueprint','editorial'].includes(id)||id===selected).map(([id,label])=>`<option value="${id}">${label}</option>`).join('');form.elements.template.value=Object.hasOwn(flyerStyles,selected)?selected:'refined-blueprint';}
let dispatcherData=null;
function renderDispatcherHealth(){
 $('#dispatcher-actions-link').href=`https://github.com/${encodeURIComponent(repo.owner)}/${encodeURIComponent(repo.name)}/actions/workflows/dispatch.yml`;
 const health=dispatcherHealth(dispatcherData),panel=$('.dispatcher-health');panel.dataset.state=health.state;
 const needsAttention=health.state==='failed'||health.state==='stale';
 $('#dispatcher-health-title').textContent=health.state==='healthy'?'Recent check succeeded':health.state==='delayed'?'Scheduled check delayed':health.state==='failed'?'Needs attention — check failed':health.state==='stale'?'Needs attention — no recent check':'Status unavailable';
 // Keep routine diagnostics below campaigns; actionable problems belong near the top.
 const anchor=needsAttention?$('#preview-banner'):$('#campaign-list');
 if(anchor.nextElementSibling!==panel)anchor.after(panel);
 $('#dispatcher-last-run').textContent='Last successful live run: '+(health.at?format(health.at)+' '+timeZoneName(health.at,config.timezone):'Not recorded');
 const warning=$('#dispatcher-warning');warning.textContent=!token&&health.state==='stale'?health.message.replace('Check Actions or run the dispatcher manually.','Connect a repository to run it manually, or open Actions.'):health.message;warning.dataset.state=health.state;warning.hidden=!needsAttention;$('#dispatcher-detail-message').textContent=warning.textContent;
}
async function refreshDispatcherHealth(){const generation=connectionGeneration;let data=null;try{if(token){const result=await api(`contents/data/dispatcher-health.json?ref=${encodeURIComponent(repo.branch)}`,{optional:true,cache:'no-store'});data=result?JSON.parse(decode(result.content)):null;}else{const response=await fetch('./data/dispatcher-health.json',{cache:'no-store'});data=response.ok?await response.json():null;}}catch{}if(generation!==connectionGeneration)return;dispatcherData=data;renderDispatcherHealth();}
