const detailFitObserver=new ResizeObserver(fitCampaignDetail);for(const target of [$('#detail-content'),$('#detail .dialog-heading'),$('#detail-actions')])detailFitObserver.observe(target);
function mountDetailTabs(buttonSelector,panelSelector,key,panelKey){
 const dialog=$('#detail'),tabs=[...dialog.querySelectorAll(buttonSelector)];
 function select(tab){
  for(const button of tabs){const active=button===tab;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;}
  if(key==='detailInfo')$('#detail-content').scrollTop=0;
  for(const panel of dialog.querySelectorAll(panelSelector)){panel.hidden=panel.dataset[panelKey]!==tab.dataset[key];if(!panel.hidden&&key==='detailInfo'){const primary=panel.querySelector('.detail-description,.detail-history');if(primary)primary.open=true;}}
 }
 for(const tab of tabs){tab.addEventListener('click',()=>select(tab));tab.addEventListener('keydown',event=>{let index=tabs.indexOf(tab);if(event.key==='ArrowRight')index=(index+1)%tabs.length;else if(event.key==='ArrowLeft')index=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')index=0;else if(event.key==='End')index=tabs.length-1;else return;event.preventDefault();select(tabs[index]);tabs[index].focus();});}
 select(tabs[0]);
}

function detail(c){
 const eventLink=$('#detail-event-page'),eventURL=!campaignIsDeleted(c)?memberEventURL(c):'';
 eventLink.hidden=!eventURL;if(eventURL)eventLink.href=eventURL;else eventLink.removeAttribute('href');
 $('#detail-error').hidden=true;$('#detail-title').textContent=c.title;
 const groupme=groupmeEnabled()&&groupmeBotMode(),story=campaignImage(c,'story'),warnings=campaignWarnings(c);
 const previewTabs=[['feed','Feed','detail-instagram-preview'],['story','Story','detail-story-preview'],...(groupme?[['groupme','GroupMe','detail-groupme-preview']]:[])];
 const lines=channels().map(k=>{let time='On next dispatcher run';try{time=channelSchedule(c,k);}catch{time='Invalid schedule';}const r=c.results?.[k]||{},link=safeURL(r.permalink||r.eventUrl||r.url);return `<li><strong>${k==='groupme'?(groupmeBotMode()?'GroupMe announcement':'GroupMe event'):k==='feed'?'Instagram feed':'Instagram story'} · ${esc(channelStateLabel(c,k))}</strong><time>${esc(postedTime(c,k)?format(postedTime(c,k)):time)}</time>${link?`<a href="${esc(link)}" target="_blank" rel="noreferrer">Open published result ↗</a>`:''}${r.eventId?`<span>Event ID: ${esc(r.eventId)}</span>`:''}</li>`;}).join('');
 $('#detail-content').innerHTML=`<section class="detail-preview-pane" aria-label="Campaign previews"><div class="detail-preview-tabs" role="tablist" aria-label="Preview channel">${previewTabs.map(([key,label,id])=>`<button type="button" role="tab" id="detail-tab-${key}" data-detail-preview="${key}" aria-controls="${id}" aria-selected="${key==='feed'}" tabindex="${key==='feed'?0:-1}">${label}</button>`).join('')}</div><div id="detail-instagram-preview" class="detail-preview-panel" data-detail-panel="feed" role="tabpanel" aria-labelledby="detail-tab-feed"></div><div id="detail-story-preview" class="detail-preview-panel" data-detail-panel="story" role="tabpanel" aria-labelledby="detail-tab-story" hidden>${story?`<div class="detail-images"><figure><img src="${esc(story)}" alt="${esc(c.title)} · story flyer" loading="lazy"><figcaption>Instagram story</figcaption><p class="image-unavailable field-help" hidden>Preview unavailable. If this campaign was just saved, check again after Actions finishes.</p></figure></div>`:'<p class="detail-preview-empty">No Story artwork available yet.</p>'}</div>${groupme?'<div id="detail-groupme-preview" class="detail-preview-panel" data-detail-panel="groupme" role="tabpanel" aria-labelledby="detail-tab-groupme" hidden></div>':''}</section>
 <section class="detail-info-pane" aria-label="Campaign overview"><div class="detail-info-tabs" role="tablist" aria-label="Campaign information">${[['overview','Overview'],['details','Event details'],['activity','Activity']].map(([key,label])=>`<button type="button" role="tab" data-detail-info="${key}" id="detail-info-tab-${key}" aria-controls="detail-info-${key}" aria-selected="${key==='overview'}" tabindex="${key==='overview'?0:-1}">${label}</button>`).join('')}</div>
<div id="detail-info-overview" data-detail-info-panel="overview" role="tabpanel" aria-labelledby="detail-info-tab-overview"> <div class="detail-overview"><div class="detail-overview-status"><span class="badge ${status(c)}">${status(c)}</span>${c.demo?'<span class="badge example">Example campaign · never published</span>':''}</div><p class="detail-event-meta">${esc(format(c.start))} – ${esc(format(c.end))} · ${esc(timeZoneName(c.start,config.timezone))}<br>${esc(c.location?.name||c.location||'Location to be confirmed')}${c.food?' · Food provided':''}</p></div>
 <section class="detail-posting" aria-label="Posting status"><h3>Posting status</h3>${stepTrack(c)}</section>
 ${warnings.length?`<details class="detail-warning-details"><summary>${warnings.length} ${warnings.length===1?'warning':'warnings'} need attention</summary>${scheduleWarningMarkup(c)}</details>`:''}
 <section class="detail-insights" aria-label="Recorded insights"><h3>Insights</h3><p class="field-help">Recorded snapshots, not live counts.</p>${campaignInsightsMarkup(c,config)}<details class="detail-all-insights"><summary>All channel metrics &amp; snapshots</summary>${insightsDetail(c)}</details></section>
</div><div id="detail-info-details" data-detail-info-panel="details" role="tabpanel" aria-labelledby="detail-info-tab-details" hidden> <details class="detail-description"><summary>Event description &amp; extras</summary><p class="detail-description-copy">${esc(c.description||'No description provided.')}</p>${advertisingDetail(c)}</details>
 <details class="detail-notes"><summary>What worked / officer notes</summary><p class="caption">${esc(c.notes||'No notes yet. Edit this campaign to capture what the next team should know.')}</p></details>
 ${!c.demo?`<details class="campaign-management detail-management"><summary>Manage campaign</summary><p class="field-help">Both actions stop pending posts. Already published posts stay published.</p><div class="campaign-management-actions"><div>${!c.cancelled?`<button data-cancel="${esc(c.id)}" aria-describedby="campaign-cancel-help">Cancel campaign</button>`:'<strong class="campaign-cancelled-label">Campaign cancelled</strong>'}<p id="campaign-cancel-help" class="field-help">${c.cancelled?'Pending posts are stopped. The campaign stays in the archive.':'Stop pending posts and keep this campaign in the archive, marked cancelled.'}</p></div><div><button data-delete="${esc(c.id)}" aria-describedby="campaign-delete-help">Delete from hub</button><p id="campaign-delete-help" class="field-help">Remove this campaign from the dashboard and archive. Publishing history is retained.</p></div></div></details>`:''}</div><div id="detail-info-activity" data-detail-info-panel="activity" role="tabpanel" aria-labelledby="detail-info-tab-activity" hidden> <details class="detail-history"><summary>Campaign timeline${c.log?.length?` · ${c.log.length} log entries`:''}</summary><ul class="timeline">${lines}${(c.log||[]).map(x=>`<li>${esc(x.message||x.action||x.event||JSON.stringify(x))}<time>${esc(x.at||x.timestamp||'')}</time></li>`).join('')}</ul></details>
</div></section>`;
 $('#detail-actions').innerHTML=`<span>${esc(c.year)} · revision ${c.revision||0}</span><button data-export="${esc(c.id)}">Export JSON</button><button data-duplicate="${esc(c.id)}">Duplicate</button>${!c.demo?`<button class="primary" data-edit="${esc(c.id)}">Edit campaign</button>`:''}`;
 mountCampaignInstagramPreview($('#detail-instagram-preview'),c,config);
 mountDetailArtworkPreview($('#detail-content'),c,config);
 if(groupme)mountGroupMePreview($('#detail-groupme-preview'),c,config);
 mountDetailTabs('[data-detail-preview]','[data-detail-panel]','detailPreview','detailPanel');mountDetailTabs('[data-detail-info]','[data-detail-info-panel]','detailInfo','detailInfoPanel');$('#detail').showModal();fitCampaignDetail();$('#detail-content').scrollTop=0;$('#detail-title').focus();
}

