 const isCollapsed=()=>desktop.matches&&(root.classList.contains('sidebar-collapsed')||(!root.classList.contains('sidebar-expanded')&&tablet.matches));
 const sync=()=>{const collapsed=isCollapsed();button?.setAttribute('aria-expanded',String(!collapsed));button?.setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar');if(button)button.title=collapsed?'Expand sidebar':'Collapse sidebar';};
 try{const saved=localStorage.getItem('social-hub-sidebar-collapsed');root.classList.toggle('sidebar-collapsed',saved==='true');root.classList.toggle('sidebar-expanded',saved==='false');}catch{}
